-- 1) starter question library (9 sets, 54 questions)
insert into public.library (id, title, topic, industry, questions, answers, ord) values
  ('lib-cyber', 'Cyber Security Basics', 'Cyber Security', 'any', $lib$[{"id":"cy1","type":"mcq","topic":"Cyber Security","q":"An email says your account will be closed in 2 hours unless you 'verify' your password. What should you do?","options":["Click the link quickly","Reply with your password","Report it as phishing and delete it","Forward it to a colleague to check"],"explain":"Urgency plus a request for credentials is a classic phishing sign. Report it using your company's phishing button."},{"id":"cy2","type":"tf","topic":"Cyber Security","q":"It's safe to reuse a strong password on several work systems.","explain":"If one system leaks, every system with the same password is exposed. Use a password manager and unique passwords."},{"id":"cy3","type":"mcq","topic":"Cyber Security","q":"Which of these is the strongest password?","options":["Summer2026!","P@ssw0rd","river-Lamp-kite-73-Mango","Company123"],"explain":"Long passphrases of random words are far harder to crack than short 'complex' words."},{"id":"cy4","type":"match","topic":"Cyber Security","q":"Match each threat to what it means","left":["Phishing","Malware","Tailgating","Vishing"],"right":["Scam by phone call","Harmful software","Fake message that tricks you into acting","Following someone through a secure door"],"explain":"Knowing the names helps you report attacks quickly and accurately."},{"id":"cy5","type":"tf","topic":"Cyber Security","q":"You should lock your screen every time you leave your desk, even for a minute.","explain":"An unlocked screen lets anyone act as you. Windows + L (or Ctrl + Cmd + Q on Mac) takes a second."},{"id":"cy6","type":"order","topic":"Cyber Security","q":"You clicked a suspicious link. Put the steps in order.","items":["Report it to IT security","Change passwords from a safe device","Watch for unusual activity","Disconnect from the network"],"explain":"Contain first, then report, then recover. Reporting fast limits the damage."}]$lib$::jsonb, $lib${"cy1":"2","cy2":"F","cy3":"2","cy4":"2,1,3,0","cy5":"T","cy6":"3,0,1,2"}$lib$::jsonb, 1),
  ('lib-privacy', 'Data Privacy Essentials', 'Data Privacy', 'any', $lib$[{"id":"dp1","type":"mcq","topic":"Data Privacy","q":"What is personal data?","options":["Only ID card numbers","Any information that can identify a person","Only data stored on paper","Only customer bank details"],"explain":"Names, emails, phone numbers, photos and IDs are all personal data when they can identify someone."},{"id":"dp2","type":"tf","topic":"Data Privacy","q":"It's fine to email a customer list to your personal address so you can work from home.","explain":"Company data must stay on approved systems. Personal email is outside the company's controls."},{"id":"dp3","type":"mcq","topic":"Data Privacy","q":"A customer asks what data you hold about them. What do you do?","options":["Ignore it","Send everything by WhatsApp","Follow the data request process and verify their identity","Tell them it's confidential"],"explain":"People have a right to access their data, but identity must be verified first and the official process used."},{"id":"dp4","type":"tf","topic":"Data Privacy","q":"Collect only the personal data you actually need for the task.","explain":"This is 'data minimisation' — less data means less risk."},{"id":"dp5","type":"match","topic":"Data Privacy","q":"Match each principle to its meaning","left":["Minimisation","Accuracy","Retention","Security"],"right":["Keep data correct and up to date","Collect only what you need","Protect data from loss or misuse","Keep data only as long as needed"],"explain":"These principles appear in most privacy laws, from GDPR to local data-protection acts."},{"id":"dp6","type":"mcq","topic":"Data Privacy","q":"You found printed customer forms left at the printer. Best action?","options":["Leave them","Bin them","Return them securely and tell the owner / your manager","Take a photo"],"explain":"Treat it as a possible data incident: secure the documents and report it."}]$lib$::jsonb, $lib${"dp1":"1","dp2":"F","dp3":"2","dp4":"T","dp5":"1,0,3,2","dp6":"2"}$lib$::jsonb, 2),
  ('lib-service', 'Customer Service Excellence', 'Customer Service', 'any', $lib$[{"id":"cs1","type":"mcq","topic":"Customer Service","q":"A customer is upset. What should you do first?","options":["Explain the policy","Listen fully without interrupting","Transfer them","Offer a discount"],"explain":"People calm down when they feel heard. Listen, acknowledge, then solve."},{"id":"cs2","type":"tf","topic":"Customer Service","q":"Promising a callback time you can't meet is better than saying you don't know yet.","explain":"Broken promises damage trust more than honest uncertainty. Give a realistic time and keep it."},{"id":"cs3","type":"order","topic":"Customer Service","q":"Put the complaint-handling steps in order","items":["Follow up","Agree a solution","Listen","Apologise and empathise"],"explain":"The LAAF flow: listen, apologise, agree, follow up."},{"id":"cs4","type":"mcq","topic":"Customer Service","q":"Which phrase sounds most helpful?","options":["That's not my department","Let me find the right person and stay with you","You'll have to call again","It's the system"],"explain":"Own the problem until it reaches someone who can solve it."},{"id":"cs5","type":"tf","topic":"Customer Service","q":"Using the customer's name (when appropriate) makes service feel more personal.","explain":"Small personal touches build rapport."}]$lib$::jsonb, $lib${"cs1":"1","cs2":"F","cs3":"2,3,1,0","cs4":"1","cs5":"T"}$lib$::jsonb, 3),
  ('lib-safety', 'Workplace Health & Safety', 'Health & Safety', 'any', $lib$[{"id":"hs1","type":"mcq","topic":"Health & Safety","q":"The fire alarm sounds. What do you do?","options":["Finish your email","Use the lift","Leave by the nearest exit and go to the assembly point","Wait for your manager"],"explain":"Never use lifts in a fire. Go straight to the assembly point so wardens can count everyone."},{"id":"hs2","type":"tf","topic":"Health & Safety","q":"You should report near-misses even when nobody was hurt.","explain":"Near-misses show where the next accident could happen."},{"id":"hs3","type":"match","topic":"Health & Safety","q":"Match the sign colour to its meaning","left":["Red","Yellow","Blue","Green"],"right":["Mandatory action","Prohibition or fire equipment","Warning","Safe condition / exit"],"explain":"Safety sign colours follow ISO 7010 in most countries."},{"id":"hs4","type":"mcq","topic":"Health & Safety","q":"Good screen posture means the top of the monitor is…","options":["Well above your eyes","At or slightly below eye level","On the desk","Behind you"],"explain":"At or just below eye level keeps your neck neutral."},{"id":"hs5","type":"tf","topic":"Health & Safety","q":"A small spill can be left for the cleaners if you're busy.","explain":"Slips are among the most common workplace injuries. Clean or signal it right away."}]$lib$::jsonb, $lib${"hs1":"2","hs2":"T","hs3":"1,2,0,3","hs4":"1","hs5":"F"}$lib$::jsonb, 4),
  ('lib-ethics', 'Code of Conduct & Ethics', 'Company Policies', 'any', $lib$[{"id":"et1","type":"mcq","topic":"Company Policies","q":"A supplier offers you an expensive gift during a tender. You should…","options":["Accept quietly","Decline and report it per the gifts policy","Accept and share with the team","Ask for cash instead"],"explain":"Gifts during a tender can look like bribery. Decline and declare it."},{"id":"et2","type":"tf","topic":"Company Policies","q":"A conflict of interest only matters if you actually benefit from it.","explain":"Even the appearance of a conflict must be declared."},{"id":"et3","type":"mcq","topic":"Company Policies","q":"Where can you raise a concern anonymously?","options":["Social media","The whistleblowing channel","Nowhere","The customer"],"explain":"Whistleblowing channels protect people who speak up in good faith."},{"id":"et4","type":"tf","topic":"Company Policies","q":"Speaking up about misconduct in good faith is protected from retaliation.","explain":"Retaliation against good-faith reporters is itself misconduct."},{"id":"et5","type":"order","topic":"Company Policies","q":"You notice something that may break policy. Put the steps in order.","items":["Raise it with your manager or the ethics line","Cooperate with any review","Pause and don't join in","Note the facts"],"explain":"Stop, record, report, cooperate."}]$lib$::jsonb, $lib${"et1":"1","et2":"F","et3":"1","et4":"T","et5":"2,3,0,1"}$lib$::jsonb, 5),
  ('lib-fun', 'Friday Fun Trivia', 'General Knowledge', 'any', $lib$[{"id":"fn1","type":"mcq","topic":"General Knowledge","q":"Which planet is known as the Red Planet?","options":["Venus","Mars","Jupiter","Mercury"],"explain":"Iron oxide dust gives Mars its red colour."},{"id":"fn2","type":"tf","topic":"General Knowledge","q":"Honey never spoils if stored properly.","explain":"Low water and high acidity keep bacteria out — edible honey has been found in ancient tombs."},{"id":"fn3","type":"mcq","topic":"General Knowledge","q":"How many minutes are in a full day?","options":["1,240","1,440","1,600","2,400"],"explain":"24 × 60 = 1,440."},{"id":"fn4","type":"match","topic":"General Knowledge","q":"Match the country to its capital","left":["Japan","Australia","Canada","Brazil"],"right":["Canberra","Brasília","Ottawa","Tokyo"],"explain":"Canberra, Ottawa and Brasília catch lots of people out."},{"id":"fn5","type":"tf","topic":"General Knowledge","q":"Lightning never strikes the same place twice.","explain":"Tall buildings are struck many times a year."}]$lib$::jsonb, $lib${"fn1":"1","fn2":"T","fn3":"1","fn4":"3,0,2,1","fn5":"F"}$lib$::jsonb, 6),
  ('lib-aml', 'AML Sprint', 'AML & Compliance', 'bank', $lib$[{"id":"aml-a1","type":"mcq","topic":"AML & Compliance","q":"A customer deposits LKR 950,000 in cash every day this week — always just under the reporting threshold. What is this pattern called?","explain":"Splitting cash into amounts below the LKR 1 million reporting threshold to dodge Cash Transaction Reports is structuring. Escalate it for a possible STR.","options":["Structuring","Integration","Layering","Diversification"]},{"id":"aml-a2","type":"mcq","topic":"AML & Compliance","q":"Cash transactions of at least how much must be reported to the FIU as a Cash Transaction Report?","explain":"Under the Financial Transactions Reporting Act, cash transactions of LKR 1 million or more (or the foreign-currency equivalent) are reported to the FIU.","options":["LKR 500,000","LKR 1,000,000","LKR 2,000,000","LKR 5,000,000"]},{"id":"aml-a3","type":"tf","topic":"AML & Compliance","q":"It's fine to tell a customer we've filed a Suspicious Transaction Report about them, as long as we're polite about it.","explain":"Never. Alerting a customer about an STR is 'tipping off' — an offence. Keep reports strictly confidential."},{"id":"aml-a4","type":"mcq","topic":"AML & Compliance","q":"In customer due diligence, what does PEP stand for?","explain":"A PEP holds (or held) a prominent public role. They and their close associates need enhanced due diligence.","options":["Priority Exempt Party","Politically Exposed Person","Pre-Evaluated Profile","Permanent Economic Partner"]},{"id":"aml-a5","type":"match","topic":"AML & Compliance","q":"Match each term to its meaning","explain":"These four terms make up most AML conversations. The FIU sits within the Central Bank of Sri Lanka.","left":["KYC","STR","CDD","FIU"],"right":["Customer Due Diligence","Financial Intelligence Unit","Suspicious Transaction Report","Know Your Customer"]},{"id":"aml-a6","type":"order","topic":"Operations","q":"Put the steps for onboarding a new customer in the right order","explain":"Verification and screening always come before the account goes live — never open first and check later.","items":["Understand the customer's need","Open the account and hand over the welcome kit","Verify identity and screen against sanctions lists","Assess risk and record in the system","Collect ID and supporting documents"]},{"id":"aml-a7","type":"mcq","topic":"AML & Compliance","q":"Which of these customers needs Enhanced Due Diligence (EDD)?","explain":"High-risk profiles — like PEPs moving large sums — need EDD: source of funds, senior approval and closer monitoring.","options":["A salaried teacher opening a savings account","A foreign PEP opening a high-value investment account","A pensioner updating their address","A student opening a basic account"]},{"id":"aml-a8","type":"mcq","topic":"AML & Compliance","q":"Where do banks in Sri Lanka send Suspicious Transaction Reports?","explain":"STRs go to the Financial Intelligence Unit, which analyses them and works with law enforcement.","options":["Credit Information Bureau (CRIB)","Financial Intelligence Unit (FIU)","Inland Revenue Department","Securities and Exchange Commission"]}]$lib$::jsonb, $lib${"aml-a1":"0","aml-a2":"1","aml-a3":"F","aml-a4":"1","aml-a5":"3,2,0,1","aml-a6":"0,4,2,3,1","aml-a7":"1","aml-a8":"1"}$lib$::jsonb, 7),
  ('lib-bcyber', 'Cyber Shield for Banks', 'Cyber Security', 'bank', $lib$[{"id":"bcyber-c1","type":"mcq","topic":"Cyber Security","q":"Someone calls saying they're from the bank's IT team and asks for your system password to 'fix an error'. What do you do?","explain":"Real IT staff never need your password. This is a vishing attempt — report it so others get warned.","options":["Give it — IT needs it to help","Refuse, end the call and report it to IT security","Share only the first half","Send it by email instead"]},{"id":"bcyber-c2","type":"tf","topic":"Cyber Security","q":"The bank may ask a customer to read out their OTP over the phone to verify who they are.","explain":"Never. An OTP is for the customer alone. Anyone asking for one is a fraudster — tell customers this every time."},{"id":"bcyber-c3","type":"mcq","topic":"Cyber Security","q":"Which email is most likely phishing?","explain":"Urgency plus a look-alike domain are the two classic phishing tells. Check the sender and never click links you didn't expect.","options":["An HR newsletter from your usual internal address","'URGENT: verify your account in 2 hours' from yourbank-secure-login.co","A calendar invite from your manager","A system alert that doesn't ask you to click anything"]},{"id":"bcyber-c4","type":"match","topic":"Cyber Security","q":"Match each scam to how it reaches you","explain":"Same trick, different channel — the fraudster wants your credentials, OTP or money.","left":["Phishing","Vishing","Smishing","Malware"],"right":["Voice calls","SMS messages","Fake emails and websites","Harmful software on a device"]},{"id":"bcyber-c5","type":"mcq","topic":"Cyber Security","q":"Which password is strongest?","explain":"Long passphrases of unrelated words, with a number and symbol, beat short 'complex' passwords that are easy to guess.","options":["Password@123","Harbor2024!","Tea!Lamp9-River-Kite","12345678"]},{"id":"bcyber-c6","type":"tf","topic":"Cyber Security","q":"Leaving your workstation unlocked for 'just two minutes' inside the branch is fine.","explain":"Lock it every time (Windows + L). Two minutes is enough for someone to misuse your access — and it'd be logged under your ID."},{"id":"bcyber-c7","type":"mcq","topic":"Cyber Security","q":"You clicked a suspicious link on your work PC. What should you do FIRST?","explain":"Speed matters. Isolate the machine and report immediately so IT can contain any damage.","options":["Nothing — see if anything happens","Restart the computer","Disconnect from the network and report to IT security right away","Delete the email and forget it"]}]$lib$::jsonb, $lib${"bcyber-c1":"1","bcyber-c2":"F","bcyber-c3":"1","bcyber-c4":"2,0,1,3","bcyber-c5":"2","bcyber-c6":"F","bcyber-c7":"2"}$lib$::jsonb, 8),
  ('lib-digital', 'Digital Banking Blitz', 'Digital & Payments', 'bank', $lib$[{"id":"digital-d1","type":"mcq","topic":"Digital & Payments","q":"What does CEFTS let customers do?","explain":"CEFTS (Common Electronic Fund Transfer Switch), run by LankaPay, moves money between banks in real time, any time.","options":["Clear cheques faster","Make real-time interbank transfers, 24/7","Apply for credit cards online","Buy foreign currency"]},{"id":"digital-d2","type":"mcq","topic":"Digital & Payments","q":"What is LankaQR?","explain":"LankaQR lets customers pay any participating merchant by scanning one common QR code from their banking app.","options":["A loan scheme for SMEs","Sri Lanka's national QR code payment standard","A branch queue system","A credit rating"]},{"id":"digital-d3","type":"match","topic":"Digital & Payments","q":"Match each system to what it does","explain":"Knowing which rail does what helps you pick the right option for each customer.","left":["CEFTS","SLIPS","CRIB","LankaQR"],"right":["Credit history of borrowers","Bulk interbank payments like salaries","National QR payments","Real-time interbank transfers"]},{"id":"digital-d4","type":"tf","topic":"Products & Services","q":"A CRIB report shows a borrower's credit history across lending institutions in Sri Lanka.","explain":"Yes. Lenders report to the Credit Information Bureau, so CRIB gives a picture of a borrower's facilities and repayment record."},{"id":"digital-d5","type":"order","topic":"Operations","q":"A customer reports their debit card stolen. Put your steps in order","explain":"Identify the customer, then block fast — every minute counts. Disputes and replacement come after the card is safe.","items":["Review recent transactions with the customer","Block the card immediately","Arrange a replacement card","Log a dispute for any unauthorised transactions","Verify the customer's identity"]},{"id":"digital-d6","type":"mcq","topic":"Products & Services","q":"A customer wants their salary and bill payments on their phone, without visiting the branch. Best move?","explain":"Onboarding them there and then — and doing the first transaction together — is what makes digital adoption stick.","options":["Tell them to come in every month","Help them sign up for digital banking and make a first payment together","Give them a brochure","Suggest another bank"]},{"id":"digital-d7","type":"mcq","topic":"Products & Services","q":"Who issues Sri Lanka's currency notes?","explain":"The Central Bank of Sri Lanka is the sole issuer of currency notes and coins.","options":["The Ministry of Finance","Commercial banks","The Central Bank of Sri Lanka","LankaPay"]}]$lib$::jsonb, $lib${"digital-d1":"1","digital-d2":"1","digital-d3":"3,1,0,2","digital-d4":"T","digital-d5":"4,1,0,3,2","digital-d6":"1","digital-d7":"2"}$lib$::jsonb, 9)
on conflict (id) do update set title = excluded.title, topic = excluded.topic, industry = excluded.industry,
  questions = excluded.questions, answers = excluded.answers, ord = excluded.ord;

-- 2) the super admin code. Starting code: Sandeepa (bcrypt). The console shows a red banner until it is changed.
insert into public.super_secret (id, hash, is_default)
values (1, extensions.crypt('Sandeepa', extensions.gen_salt('bf', 10)), true)
on conflict (id) do nothing;

